(() => {
  'use strict';

  const SEED = window.ROCHE_PILOT_DATA || [];
  const ROCHE_ONLY = window.ROCHE_ONLY_WARNINGS || [];
  const STORAGE_KEY = 'roche_v2_web_beta_cache';
  const APP_STATE_ID = 'roche_shared';
  const SUPA_CFG = window.ROCHE_SUPABASE || {};
  const db = (window.supabase && SUPA_CFG.url && SUPA_CFG.publishableKey) ? window.supabase.createClient(SUPA_CFG.url, SUPA_CFG.publishableKey) : null;
  let authUser = null;
  let lastRemoteUpdatedAt = '';
  let remoteSaveTimer = null;
  let remoteSaving = false;
  const TYPES = ['Suministro','Instalación','Mantenimiento','Devolución','Otros','Venta','Venta CENARES'];
  const SIMPLE_TYPES = ['Suministro','Instalación','Mantenimiento','Devolución','Otros'];
  const LOGO_BASE64 = '';

  const $ = (s, root=document) => root.querySelector(s);
  const $$ = (s, root=document) => [...root.querySelectorAll(s)];
  const esc = (v='') => String(v ?? '').replace(/[&<>"']/g, c=>({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;' }[c]));
  const nowIso = () => new Date().toISOString();
  const fmtDate = (iso) => {
    if (!iso) return '';
    const d = String(iso).slice(0,10).split('-');
    return d.length===3 ? `${d[2]}/${d[1]}/${d[0]}` : iso;
  };
  const fmtShort = (iso) => {
    if (!iso) return '';
    const d = String(iso).slice(0,10).split('-');
    if (d.length!==3) return iso;
    const months=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    return `${Number(d[2])}-${months[Number(d[1])-1]}`;
  };
  const normalizeDigits = s => String(s||'').replace(/\D/g,'');
  const uid = (p='id') => `${p}_${Date.now()}_${Math.random().toString(36).slice(2,8)}`;
  const deepClone = o => JSON.parse(JSON.stringify(o));

  function blankRecordFromSeed(s){
    return {
      ...deepClone(s), imported: true, type: '', result:'Pendiente', manualComplete:false,
      readyManual:false, cancelled:false, liquidated:false, liquidatedAt:'', closeReason:'',
      observations:'', situation:'', followUps:[], extraNotes:[], receipts:[], audit:[], grtHistory: s.previousGrt ? [{at:'',user:'Migración inicial',oldGRT:s.previousGrt,newGRT:s.grt,reason:'Actualización detectada al cruzar la data inicial'}] : [],
      cenExpected:{gr:4,actas:4,pecosas:4},
      reviewResolved: !(s.issues||[]).length,
    };
  }

  function freshState(){
    const records = SEED.filter(x => !(x.issues||[]).length).map(blankRecordFromSeed);
    const review = SEED.filter(x => (x.issues||[]).length).map(x => ({...blankRecordFromSeed(x), imported:false, reviewResolved:false}));
    return {
      version:'2.0-web-beta', currentUser:'', records, review, rocheOnly:deepClone(ROCHE_ONLY), reports:[],
      grtReceived:{}, grtLedger:{}, reportDraft:null, audit:[], settings:{cargoStart:''}
    };
  }

  let state = loadState();
  function loadState(){
    try{
      const raw = localStorage.getItem(STORAGE_KEY);
      if(raw) return JSON.parse(raw);
    }catch(e){}
    return freshState();
  }
  function cacheState(){
    try{ localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); }catch(e){}
  }
  function stateForRemote(){
    const copy=deepClone(state);
    copy.currentUser='';
    copy.version='2.0-web-beta';
    return copy;
  }
  function setSyncStatus(text,kind=''){
    const el=$('#syncStatus'); if(!el)return;
    el.textContent=text; el.className='sync-status'+(kind?' '+kind:'');
  }
  async function pushRemoteState(){
    if(!db || !authUser || remoteSaving) return;
    remoteSaving=true; setSyncStatus('● Guardando…','syncing');
    try{
      const payload={id:APP_STATE_ID,data:stateForRemote(),updated_by:authUser.id,updated_at:new Date().toISOString()};
      const {data,error}=await db.from('app_state').upsert(payload,{onConflict:'id'}).select('updated_at').single();
      if(error) throw error;
      lastRemoteUpdatedAt=data?.updated_at||payload.updated_at;
      setSyncStatus('● Sincronizado');
    }catch(err){ console.error('Supabase save',err); setSyncStatus('● Error de sincronización','error'); }
    finally{ remoteSaving=false; }
  }
  function saveState(){
    cacheState();
    if(authUser){
      clearTimeout(remoteSaveTimer);
      remoteSaveTimer=setTimeout(pushRemoteState,180);
    }
  }
  async function loadRemoteState(){
    if(!db || !authUser) return false;
    setSyncStatus('● Cargando…','syncing');
    const {data,error}=await db.from('app_state').select('data,updated_at').eq('id',APP_STATE_ID).maybeSingle();
    if(error) throw error;
    if(data?.data){
      const userName=state.currentUser;
      state=data.data;
      state.currentUser=userName;
      state.version='2.0-web-beta';
      lastRemoteUpdatedAt=data.updated_at||'';
      cacheState(); setSyncStatus('● Sincronizado'); return true;
    }
    state=freshState(); state.currentUser=displayUser(authUser); cacheState();
    await pushRemoteState();
    return true;
  }
  async function refreshRemoteIfNewer(){
    if(!db || !authUser || remoteSaving || !$('#modalBackdrop')?.classList.contains('hidden')) return;
    try{
      const {data,error}=await db.from('app_state').select('data,updated_at').eq('id',APP_STATE_ID).maybeSingle();
      if(error||!data?.data||!data.updated_at)return;
      if(lastRemoteUpdatedAt && data.updated_at<=lastRemoteUpdatedAt)return;
      const userName=state.currentUser;
      state=data.data; state.currentUser=userName; state.version='2.0-web-beta'; lastRemoteUpdatedAt=data.updated_at; cacheState(); renderAll(); setSyncStatus('● Actualizado');
    }catch(err){ console.warn('Supabase refresh',err); }
  }
  function displayUser(user){
    const meta=user?.user_metadata||{};
    if(meta.nombre) return meta.nombre;
    const email=user?.email||'';
    if(/^dahane/i.test(email)) return 'Dahane';
    if(/^lisbet/i.test(email)) return 'Lisbet';
    return email.split('@')[0]||'Usuario';
  }
  function audit(action, detail=''){
    const a={id:uid('audit'),at:nowIso(),user:state.currentUser||'—',action,detail};
    state.audit.push(a); saveState(); return a;
  }
  function toast(msg, danger=false){
    const t=$('#toast'); t.textContent=msg; t.classList.remove('hidden'); t.classList.toggle('danger',danger);
    clearTimeout(toast._t); toast._t=setTimeout(()=>t.classList.add('hidden'),2600);
  }

  function allOperational(){ return state.records.filter(r=>r.imported && !r.cancelled); }
  function getRecord(id){ return state.records.find(r=>String(r.id)===String(id)) || state.review.find(r=>String(r.id)===String(id)); }
  function groupFor(r){ return state.records.filter(x=>x.imported && !x.cancelled && x.grt===r.grt); }
  function isGRTReceived(r){ return !!((state.grtLedger&&state.grtLedger[r.grt]) || (state.grtReceived&&state.grtReceived[r.grt])); }
  function getGRTLedger(grt){ state.grtLedger=state.grtLedger||{}; if(!state.grtLedger[grt] && state.grtReceived&&state.grtReceived[grt]) state.grtLedger[grt]={at:nowIso(),user:'Migrado',sentReportId:null}; return state.grtLedger[grt]||null; }
  function setGRTReceived(grt){ state.grtLedger=state.grtLedger||{}; if(!state.grtLedger[grt]) state.grtLedger[grt]={at:nowIso(),user:state.currentUser,sentReportId:null}; state.grtReceived[grt]=true; }
  function grtUnsent(grt){ const g=getGRTLedger(grt); return !!g && !g.sentReportId; }

  function sumDocs(r, unsentOnly=false){
    const out={grt:0,gr:0,grCopies:0,actas:0,pecosas:0,factura:0,oc:0,extras:[]};
    (r.receipts||[]).forEach(m=>{
      if(unsentOnly && m.sentReportId) return;
      const d=m.docs||{};
      ['grt','gr','grCopies','actas','pecosas','factura','oc'].forEach(k=>out[k]+=Number(d[k]||0));
      (d.extras||[]).forEach(x=>out.extras.push(x));
    });
    return out;
  }
  function hasUnsent(r){
    return (r.receipts||[]).some(m=>!m.sentReportId && docCount(m.docs)>0);
  }
  function docCount(d={}){
    return ['grt','gr','grCopies','actas','pecosas','factura','oc'].reduce((n,k)=>n+Number(d[k]||0),0)+(d.extras||[]).length;
  }
  function latestReceiptDateForUnsent(r){
    const arr=(r.receipts||[]).filter(m=>!m.sentReportId && docCount(m.docs)>0).map(m=>m.at).sort();
    return arr.length?arr[arr.length-1]:'';
  }
  function latestReceiptDateForReport(r, reportId){
    const arr=(r.receipts||[]).filter(m=>m.sentReportId===reportId).map(m=>m.at).sort();
    return arr.length?arr[arr.length-1]:'';
  }

  function resolvedStateFromDocs(r){
    const d=sumDocs(r,false); const grt=isGRTReceived(r) || d.grt>0;
    const any = grt || d.gr>0 || d.grCopies>0 || d.actas>0 || d.pecosas>0 || d.factura>0 || d.oc>0 || d.extras.length>0;
    if(!any) return 'Pendiente';
    if(!r.type) return 'Parcial';
    let complete=false;
    if(SIMPLE_TYPES.includes(r.type)) complete=grt && d.gr>=1;
    if(r.type==='Venta'){
      const factResolved = r.facturaState==='Recibido' || r.facturaState==='No aplica';
      const ocResolved = r.ocState==='Recibido' || r.ocState==='No aplica';
      complete=grt && d.gr>=1 && factResolved && ocResolved;
    }
    if(r.type==='Venta CENARES'){
      const factResolved = r.facturaState==='Recibido' || r.facturaState==='No aplica';
      const ocResolved = r.ocState==='Recibido' || r.ocState==='No aplica';
      complete=grt && d.grCopies>=4 && d.actas>=4 && d.pecosas>=4 && factResolved && ocResolved;
    }
    if(r.manualComplete) complete=true;
    return complete?'Completo':'Parcial';
  }
  function recalc(r){
    if(r.cancelled) return;
    if(r.liquidated){ r.result='Completo'; return; }
    r.result=resolvedStateFromDocs(r);
  }
  function recalcAll(){ state.records.forEach(recalc); }
  function isReady(r){
    if(r.cancelled || r.liquidated) return false;
    if(!hasUnsent(r)) return false;
    return r.result==='Completo' || (r.result==='Parcial' && r.readyManual);
  }
  function docsText(r, unsentOnly=false){
    const d=sumDocs(r,unsentOnly), parts=[];
    if((!unsentOnly && isGRTReceived(r)) || (unsentOnly && grtUnsent(r.grt))) parts.push('GRT');
    if(r.type==='Venta CENARES'){
      if(d.grCopies) parts.push(`${d.grCopies} GR`);
      if(d.actas) parts.push(`${d.actas} Actas`);
      if(d.pecosas) parts.push(`${d.pecosas} Pecosas`);
    }else if(d.gr) parts.push('GR');
    if(d.factura) parts.push('Factura');
    if(d.oc) parts.push('OC');
    d.extras.forEach(x=>parts.push(x));
    return parts.join(' + ') || '—';
  }
  function docsTextLower(r, unsentOnly=false){ return docsText(r,unsentOnly).replace(/GRT/g,'grt').replace(/GR/g,'gr').replace(/Factura/g,'fact').replace(/OC/g,'oc'); }

  function sumDocsBy(r, predicate){
    const out={grt:0,gr:0,grCopies:0,actas:0,pecosas:0,factura:0,oc:0,extras:[]};
    (r.receipts||[]).forEach(m=>{
      if(!predicate(m)) return;
      const d=m.docs||{};
      ['grt','gr','grCopies','actas','pecosas','factura','oc'].forEach(k=>out[k]+=Number(d[k]||0));
      (d.extras||[]).forEach(x=>out.extras.push(x));
    });
    return out;
  }
  function docsObjectText(r,d,includeGRT=false){
    const parts=[];
    if(includeGRT) parts.push('GRT');
    if(r.type==='Venta CENARES'){
      if(d.grCopies) parts.push(`${d.grCopies} GR`);
      if(d.actas) parts.push(`${d.actas} Actas`);
      if(d.pecosas) parts.push(`${d.pecosas} Pecosas`);
    }else if(d.gr) parts.push('GR');
    if(d.factura) parts.push('Factura');
    if(d.oc) parts.push('OC');
    (d.extras||[]).forEach(x=>parts.push(x));
    return parts.join(' + ') || '—';
  }
  function sentBreakdown(r){
    const byReport={};
    (r.receipts||[]).forEach(m=>{
      if(!m.sentReportId) return;
      const id=m.sentReportId;
      if(!byReport[id]) byReport[id]={grt:false,docs:{grt:0,gr:0,grCopies:0,actas:0,pecosas:0,factura:0,oc:0,extras:[]}};
      const d=m.docs||{};
      ['grt','gr','grCopies','actas','pecosas','factura','oc'].forEach(k=>byReport[id].docs[k]+=Number(d[k]||0));
      (d.extras||[]).forEach(x=>byReport[id].docs.extras.push(x));
    });
    const ledger=getGRTLedger(r.grt);
    if(ledger?.sentReportId){
      const id=ledger.sentReportId;
      if(!byReport[id]) byReport[id]={grt:false,docs:{grt:0,gr:0,grCopies:0,actas:0,pecosas:0,factura:0,oc:0,extras:[]}};
      byReport[id].grt=true;
    }
    return Object.entries(byReport).map(([id,x])=>({reportId:id,cargo:reportLabel(id),text:docsObjectText(r,x.docs,x.grt)}));
  }
  function missingDocsText(r){
    const d=sumDocs(r,false), miss=[];
    if(!r.type) return 'Definir tipo de guía';
    if(!isGRTReceived(r)) miss.push('GRT');
    if(SIMPLE_TYPES.includes(r.type)){
      if(d.gr<1) miss.push('GR');
    }else if(r.type==='Venta'){
      if(d.gr<1) miss.push('GR');
      if(!['Recibido','No aplica'].includes(r.facturaState||'')) miss.push(r.facturaState==='Pendiente'?'Factura':'Factura (sin definir)');
      if(!['Recibido','No aplica'].includes(r.ocState||'')) miss.push(r.ocState==='Pendiente'?'OC':'OC (sin definir)');
    }else if(r.type==='Venta CENARES'){
      if(d.grCopies<4) miss.push(`${4-d.grCopies} GR`);
      if(d.actas<4) miss.push(`${4-d.actas} Actas`);
      if(d.pecosas<4) miss.push(`${4-d.pecosas} Pecosas`);
      if(!['Recibido','No aplica'].includes(r.facturaState||'')) miss.push(r.facturaState==='Pendiente'?'Factura':'Factura (sin definir)');
      if(!['Recibido','No aplica'].includes(r.ocState||'')) miss.push(r.ocState==='Pendiente'?'OC':'OC (sin definir)');
    }
    return miss.join(' + ') || 'Nada';
  }
  function receiptStatusHtml(r){
    const sent=sentBreakdown(r);
    const sentHtml=sent.length?sent.map(x=>`<div class="sent-line"><b>${esc(x.text)}</b><span>Cargo ${esc(x.cargo)}</span></div>`).join(''):'<span class="muted">Nada enviado aún</span>';
    return `<div class="receipt-status-grid">
      <div class="receipt-status-card received"><span>RECIBIDO ACUMULADO</span><strong>${esc(docsText(r,false))}</strong><small>Factura: ${esc(r.facturaState||'Sin definir')} · OC: ${esc(r.ocState||'Sin definir')}</small></div>
      <div class="receipt-status-card sent"><span>YA ENVIADO A ROCHE</span>${sentHtml}</div>
      <div class="receipt-status-card unsent"><span>RECIBIDO PENDIENTE DE ENVIAR</span><strong>${esc(docsText(r,true))}</strong></div>
      <div class="receipt-status-card missing"><span>FALTA POR RECIBIR / COMPLETAR</span><strong>${esc(missingDocsText(r))}</strong></div>
    </div>`;
  }

  // ---------- Login / navigation ----------
  async function startAuthenticatedSession(user){
    authUser=user;
    state.currentUser=displayUser(user);
    try{ await loadRemoteState(); }
    catch(err){ console.error(err); setSyncStatus('● No se pudo cargar la base','error'); toast('No se pudo cargar la base compartida',true); }
    state.currentUser=displayUser(user);
    showApp();
    audit('Inicio de sesión');
  }
  $('#loginForm').addEventListener('submit',async e=>{
    e.preventDefault();
    if(!db){ $('#loginError').textContent='No se pudo inicializar Supabase.'; $('#loginError').classList.remove('hidden'); return; }
    const email=$('#loginEmail').value.trim(), password=$('#loginPassword').value;
    const btn=$('#loginSubmit'); btn.disabled=true; btn.textContent='INGRESANDO…'; $('#loginError').classList.add('hidden');
    try{
      const {data,error}=await db.auth.signInWithPassword({email,password});
      if(error) throw error;
      await startAuthenticatedSession(data.user);
      $('#loginPassword').value='';
    }catch(err){ $('#loginError').textContent='No se pudo iniciar sesión. Revisa correo y contraseña.'; $('#loginError').classList.remove('hidden'); }
    finally{ btn.disabled=false; btn.textContent='INICIAR SESIÓN'; }
  });
  $('#logoutBtn').addEventListener('click',async()=>{
    try{ await pushRemoteState(); await db?.auth.signOut(); }catch(e){}
    authUser=null; state.currentUser=''; cacheState(); $('#appView').classList.add('hidden'); $('#loginView').classList.remove('hidden'); setSyncStatus('● Desconectado','error');
  });
  $('#backupBtn').addEventListener('click',()=>{
    const payload={exportedAt:nowIso(),appVersion:'2.0-web-beta',state:stateForRemote()};
    const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}), a=document.createElement('a');
    a.href=URL.createObjectURL(blob); a.download=`ROCHE_RESPALDO_${new Date().toISOString().slice(0,10)}.json`; a.click(); setTimeout(()=>URL.revokeObjectURL(a.href),1000);
    audit('Respaldo exportado'); toast('Respaldo descargado');
  });
  $('#restoreBtn').addEventListener('click',()=>$('#restoreFile').click());
  $('#restoreFile').addEventListener('change',async e=>{
    const file=e.target.files?.[0]; if(!file)return;
    try{
      const parsed=JSON.parse(await file.text()); const restored=parsed.state||parsed;
      if(!restored || !Array.isArray(restored.records) || !Array.isArray(restored.reports)) throw new Error('Formato no válido');
      if(!confirm('¿Restaurar este respaldo en la base compartida? Reemplazará el estado actual para todos los usuarios.'))return;
      const user=state.currentUser; state=restored; state.currentUser=user; state.version='2.0-web-beta'; saveState(); await pushRemoteState(); renderAll(); toast('Respaldo restaurado en la base compartida');
    }catch(err){ toast('No pude restaurar ese archivo de respaldo',true); } finally { e.target.value=''; }
  });
  $$('.nav-btn').forEach(b=>b.addEventListener('click',()=>openPage(b.dataset.page)));
  function openPage(page){
    $$('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.page===page));
    $$('.page').forEach(p=>p.classList.add('hidden')); $('#page-'+page).classList.remove('hidden');
    const titles={quick:'Registro rápido',pending:'Pendientes / Parciales',ready:'Listos para enviar',general:'Reporte general',history:'Historial Roche',closed:'Liquidados',import:'Importar data'};
    $('#pageTitle').textContent=titles[page]||''; renderAll(); refreshRemoteIfNewer();
  }
  function showApp(){
    $('#loginView').classList.add('hidden'); $('#appView').classList.remove('hidden'); $('#activeUser').textContent=state.currentUser; renderAll(); setSyncStatus('● Sincronizado');
  }

  // ---------- Modal ----------
  function openModal(title, subtitle, html, cls=''){
    $('#modalTitle').textContent=title; $('#modalSubtitle').textContent=subtitle||''; $('#modalBody').innerHTML=html;
    $('#modal').className='modal '+cls; $('#modalBackdrop').classList.remove('hidden');
  }
  function closeModal(){ $('#modalBackdrop').classList.add('hidden'); $('#modalBody').innerHTML=''; }
  $('#modalClose').addEventListener('click',closeModal);
  $('#modalBackdrop').addEventListener('click',e=>{ if(e.target.id==='modalBackdrop') closeModal(); });



  // ---------- Always-visible horizontal table scrollbar ----------
  const floatingHScroll=$('#floatingHScroll');
  const floatingHScrollInner=$('.floating-hscroll-inner',floatingHScroll);
  let floatingScrollTarget=null, floatingScrollSync=false;
  function visibleOverflowTables(){
    const modalOpen=!$('#modalBackdrop').classList.contains('hidden');
    const scope=modalOpen?$('#modal'):(document.querySelector('.page:not(.hidden)')||$('#appView'));
    return $$('.table-wrap,.package-table-wrap,.preview-sheet',scope).filter(w=>{
      const r=w.getBoundingClientRect();
      return w.scrollWidth>w.clientWidth+4 && r.bottom>0 && r.top<window.innerHeight && r.width>80 && r.height>25;
    });
  }
  function updateFloatingHScroll(){
    if(!floatingHScroll||!floatingHScrollInner)return;
    const candidates=visibleOverflowTables();
    if(!candidates.length){ floatingScrollTarget=null; floatingHScroll.classList.add('hidden'); return; }
    // Prefer the widest currently visible table; modal tables are already scoped above.
    floatingScrollTarget=candidates.sort((a,b)=>(b.getBoundingClientRect().width)-(a.getBoundingClientRect().width))[0];
    const r=floatingScrollTarget.getBoundingClientRect();
    const left=Math.max(8,r.left), right=Math.min(window.innerWidth-8,r.right);
    floatingHScroll.style.left=`${left}px`; floatingHScroll.style.width=`${Math.max(80,right-left)}px`;
    floatingHScrollInner.style.width=`${floatingScrollTarget.scrollWidth}px`;
    floatingScrollSync=true; floatingHScroll.scrollLeft=floatingScrollTarget.scrollLeft; floatingScrollSync=false;
    floatingHScroll.classList.remove('hidden');
  }
  floatingHScroll?.addEventListener('scroll',()=>{
    if(floatingScrollSync||!floatingScrollTarget)return;
    floatingScrollSync=true; floatingScrollTarget.scrollLeft=floatingHScroll.scrollLeft; floatingScrollSync=false;
  });
  document.addEventListener('scroll',e=>{
    if(e.target===floatingScrollTarget && !floatingScrollSync){
      floatingScrollSync=true; floatingHScroll.scrollLeft=floatingScrollTarget.scrollLeft; floatingScrollSync=false;
    }
    requestAnimationFrame(updateFloatingHScroll);
  },true);
  window.addEventListener('resize',()=>requestAnimationFrame(updateFloatingHScroll));
  const floatingObserver=new MutationObserver(()=>requestAnimationFrame(updateFloatingHScroll));
  floatingObserver.observe(document.body,{subtree:true,childList:true,attributes:true,attributeFilter:['class','style']});


  // ---------- Quick search ----------
  $('#quickSearchBtn').addEventListener('click',doQuickSearch);
  $('#quickSearch').addEventListener('keydown',e=>{ if(e.key==='Enter') doQuickSearch(); });
  function doQuickSearch(){
    const q=$('#quickSearch').value.trim(); const out=$('#quickResult');
    if(!q){ toast('Escribe una GR o sus últimos dígitos',true); return; }
    const digits=normalizeDigits(q); const txt=q.toUpperCase();
    let matches=allOperational().filter(r=>{
      if(txt.includes('-') && r.gr.toUpperCase()===txt) return true;
      const rd=normalizeDigits(r.gr); return digits && rd.endsWith(digits);
    });
    if(!matches.length){ out.classList.remove('hidden'); out.innerHTML=`<div class="not-found"><strong>No encontré una GR con “${esc(q)}”.</strong><br><span class="muted">Revisa también Importar data → Por revisar.</span></div>`; return; }
    out.classList.remove('hidden');
    if(matches.length>1){
      out.innerHTML=`<div class="match-list"><strong>Encontré ${matches.length} coincidencias. Elige una:</strong>${matches.slice(0,12).map(r=>`<button class="match-row" data-open-gr="${r.id}"><b>${esc(r.gr)}</b><span>${esc(r.grt)} · ${esc(r.district)}</span></button>`).join('')}</div>`;
      $$('[data-open-gr]',out).forEach(b=>b.addEventListener('click',()=>openQuickRecord(getRecord(b.dataset.openGr))));
    }else openQuickRecord(matches[0]);
  }
  function openQuickRecord(r){
    const group=groupFor(r);
    if(group.length>1){
      $('#quickResult').innerHTML=`<div class="group-found"><div><div class="eyebrow">GRT CON VARIAS GR</div><h3>${esc(r.gr)}</h3><p>Esta GR pertenece a <strong>${esc(r.grt)}</strong>, que tiene <strong>${group.length} GR relacionadas</strong>.</p></div><div class="group-actions"><button class="btn huge" id="singleFromGroup">REGISTRAR SOLO ESTA GR</button><button class="btn primary huge" id="packageFromGroup">REGISTRAR PAQUETE COMPLETO · ${group.length} GR</button></div></div>`;
      $('#singleFromGroup').onclick=()=>openSingleRegistration(r);
      $('#packageFromGroup').onclick=()=>openPackageRegistration(r);
    } else openSingleRegistration(r);
  }

  function typeButtons(selected=''){
    return `<div class="type-grid">${TYPES.map(t=>`<button type="button" class="type-btn ${selected===t?'selected':''}" data-type="${esc(t)}">${esc(t).toUpperCase()}</button>`).join('')}</div>`;
  }
  function baseInfo(r){
    return `<div class="info-grid"><div><span>GR cliente</span><strong>${esc(r.gr)}</strong></div><div><span>GRT</span><strong>${esc(r.grt)}</strong></div><div><span>Pedido</span><strong>${esc(r.order||'—')}</strong></div><div><span>Distrito</span><strong>${esc(r.district)}</strong></div><div class="span2"><span>Destinatario</span><strong>${esc(r.recipient)}</strong></div><div class="span2"><span>Dirección</span><strong>${esc(r.address||'—')}</strong></div></div>`;
  }

  function openSingleRegistration(r, mode='quick'){
    const accumulated=docsText(r,false);
    const html=`${baseInfo(r)}
      <div class="section-block"><div class="section-label">1. Tipo de guía</div>${typeButtons(r.type)}</div>
      ${mode==='add'?`${receiptStatusHtml(r)}<div class="accumulated-box accumulated-prominent"><small>Los controles de abajo son únicamente para lo que acaba de llegar. Lo ya recibido no desaparece aunque haya sido enviado.</small></div>`:''}
      <div id="singleDocsArea" class="section-block"></div>
      <div class="modal-actions"><button class="btn" id="cancelSingle">Cancelar</button><button class="btn primary big" id="saveSingle">GUARDAR ${mode==='add'?'NUEVA RECEPCIÓN':'Y SIGUIENTE'}</button></div>`;
    openModal(mode==='add'?'Agregar documentos':'Registro rápido', mode==='add'?'Registra solamente lo que acaba de llegar. El acumulado no se modifica manualmente.':'Mira la guía física, selecciona su tipo y marca lo que llegó.', html, 'registration-modal');
    let selectedType=r.type||'';
    const renderDocs=()=>{
      const area=$('#singleDocsArea');
      if(!selectedType){ area.innerHTML='<div class="empty-hint">Selecciona primero el tipo de la guía.</div>'; return; }
      area.innerHTML=`<div class="section-label">2. Documentos recibidos ${mode==='add'?'en esta nueva recepción':''}</div>${docsControls(selectedType, r, mode)}`;
      wireExtraAdd(area);
      if(SIMPLE_TYPES.includes(selectedType) || selectedType==='Venta'){
        const mb=$('#markBoth',area); if(mb) mb.onclick=()=>{ const a=$('#docGRT',area), b=$('#docGR',area); if(a&&!a.disabled)a.checked=true; if(b)b.checked=true; };
      }
    };
    $$('.type-btn',$('#modalBody')).forEach(b=>b.onclick=()=>{ selectedType=b.dataset.type; $$('.type-btn',$('#modalBody')).forEach(x=>x.classList.toggle('selected',x===b)); renderDocs(); });
    renderDocs();
    $('#cancelSingle').onclick=closeModal;
    $('#saveSingle').onclick=()=>{
      if(!selectedType){ toast('Selecciona el tipo',true); return; }
      const data=readDocsControls($('#singleDocsArea'),selectedType,r);
      if(!data || docCount(data.docs)===0 && !data.stateOnly){ toast('Marca al menos un documento o estado recibido',true); return; }
      r.type=selectedType;
      if(data.facturaState) r.facturaState=data.facturaState;
      if(data.ocState) r.ocState=data.ocState;
      if(data.docs.grt){ setGRTReceived(r.grt); data.docs.grt=0; }
      if(docCount(data.docs)>0) r.receipts.push({id:uid('rec'),at:nowIso(),user:state.currentUser,docs:data.docs,sentReportId:null});
      r.audit.push({at:nowIso(),user:state.currentUser,action:mode==='add'?'Nueva recepción':'Registro rápido',detail:docsTextFromRaw(data.docs)});
      recalc(r); saveState(); audit(mode==='add'?'Registro de nueva recepción':'Registro rápido de GR',`${r.gr} · ${selectedType}`);
      closeModal(); $('#quickSearch').value=''; $('#quickResult').classList.add('hidden'); renderAll(); if(mode==='quick') $('#quickSearch').focus(); toast('Recepción guardada');
    };
  }

  function docsControls(type,r,mode){
    const grtAlready=isGRTReceived(r);
    const extra=`<div class="extra-docs"><div class="extra-row"><input class="extraInput" placeholder="Documento adicional (ej. Plantilla, Carta, Regularización...)"/><button type="button" class="btn addExtra">Agregar</button></div><div class="extraTags"></div></div>`;
    if(SIMPLE_TYPES.includes(type)) return `
      <div class="doc-checks large-checks"><label class="check-card ${grtAlready?'already':''}"><input id="docGRT" type="checkbox" ${grtAlready?'disabled':''}><span>GRT</span><small>${grtAlready?'Ya recibida para esta GRT':'Marcar si llegó físicamente'}</small></label><label class="check-card"><input id="docGR" type="checkbox"><span>GR</span><small>Guía física recibida</small></label></div>
      <button type="button" class="btn primary mark-both" id="markBoth">MARCAR AMBOS · GRT + GR</button>${extra}`;
    if(type==='Venta') return `
      <div class="doc-checks"><label class="check-card ${grtAlready?'already':''}"><input id="docGRT" type="checkbox" ${grtAlready?'disabled':''}><span>GRT</span><small>${grtAlready?'Ya recibida':'Marcar si llegó'}</small></label><label class="check-card"><input id="docGR" type="checkbox"><span>GR</span><small>Guía recibida</small></label></div>
      <button type="button" class="btn primary mark-both" id="markBoth">MARCAR AMBOS · GRT + GR</button>
      <div class="state-grid"><div class="field state-field"><label>Factura</label><small>Estado acumulado: <b>${esc(r.facturaState||'Sin definir')}</b></small><select id="factState"><option value="">Sin cambios</option><option>Recibido</option><option>Pendiente</option><option>No aplica</option></select></div><div class="field state-field"><label>OC</label><small>Estado acumulado: <b>${esc(r.ocState||'Sin definir')}</b></small><select id="ocState"><option value="">Sin cambios</option><option>Recibido</option><option>Pendiente</option><option>No aplica</option></select></div></div>${extra}`;
    if(type==='Venta CENARES') return `
      <div class="doc-checks"><label class="check-card ${grtAlready?'already':''}"><input id="docGRT" type="checkbox" ${grtAlready?'disabled':''}><span>GRT</span><small>${grtAlready?'Ya recibida':'Marcar si llegó'}</small></label></div>
      <div class="cenares-grid"><div class="count-box"><span>GR esperadas</span><b>4</b><label>Recibidas <input id="cntGR" type="number" min="0" max="4" value="0"></label></div><div class="count-box"><span>Actas esperadas</span><b>4</b><label>Recibidas <input id="cntActas" type="number" min="0" max="4" value="0"></label></div><div class="count-box"><span>Pecosas esperadas</span><b>4</b><label>Recibidas <input id="cntPecosas" type="number" min="0" max="4" value="0"></label></div></div>
      <div class="state-grid"><div class="field state-field"><label>Factura</label><small>Estado acumulado: <b>${esc(r.facturaState||'Sin definir')}</b></small><select id="factState"><option value="">Sin cambios</option><option>Recibido</option><option>Pendiente</option><option>No aplica</option></select></div><div class="field state-field"><label>OC</label><small>Estado acumulado: <b>${esc(r.ocState||'Sin definir')}</b></small><select id="ocState"><option value="">Sin cambios</option><option>Recibido</option><option>Pendiente</option><option>No aplica</option></select></div></div>${extra}`;
    return extra;
  }
  function wireExtraAdd(root){
    const input=$('.extraInput',root), btn=$('.addExtra',root), tags=$('.extraTags',root); if(!input||!btn||!tags)return;
    btn.onclick=()=>{ const v=input.value.trim(); if(!v)return; const el=document.createElement('span'); el.className='extra-tag'; el.dataset.value=v; el.innerHTML=`${esc(v)} <button type="button">×</button>`; $('button',el).onclick=()=>el.remove(); tags.appendChild(el); input.value=''; };
  }
  function readDocsControls(root,type,r){
    const docs={grt:0,gr:0,grCopies:0,actas:0,pecosas:0,factura:0,oc:0,extras:[]};
    const q=s=>$(s,root); if(q('#docGRT') && q('#docGRT').checked) docs.grt=1; if(q('#docGR')&&q('#docGR').checked) docs.gr=1;
    if(type==='Venta CENARES'){ docs.grCopies=Math.max(0,Math.min(4,Number(q('#cntGR')?.value||0))); docs.actas=Math.max(0,Math.min(4,Number(q('#cntActas')?.value||0))); docs.pecosas=Math.max(0,Math.min(4,Number(q('#cntPecosas')?.value||0))); }
    const fs=q('#factState')?.value||''; const os=q('#ocState')?.value||'';
    if(fs==='Recibido') docs.factura=1; if(os==='Recibido') docs.oc=1;
    $$('.extra-tag',root).forEach(x=>docs.extras.push(x.dataset.value));
    return {docs,facturaState:fs||null,ocState:os||null,stateOnly:!!fs||!!os};
  }
  function docsTextFromRaw(d={}){
    const p=[]; if(d.grt)p.push('GRT'); if(d.gr)p.push('GR'); if(d.grCopies)p.push(`${d.grCopies} GR`); if(d.actas)p.push(`${d.actas} Actas`); if(d.pecosas)p.push(`${d.pecosas} Pecosas`); if(d.factura)p.push('Factura'); if(d.oc)p.push('OC'); (d.extras||[]).forEach(x=>p.push(x)); return p.join(' + ')||'Sin documentos físicos';
  }

  // ---------- Package ----------
  function openPackageRegistration(base){
    const group=groupFor(base).sort((a,b)=>a.gr.localeCompare(b.gr));
    const recipient=base.recipient, address=base.address;
    const html=`<div class="package-head"><div><span>GRT</span><strong>${esc(base.grt)}</strong></div><div><span>Destinatario</span><strong>${esc(recipient)}</strong></div><div class="wide"><span>Dirección</span><strong>${esc(address||'—')}</strong></div><label class="shared-grt"><input id="pkgGRT" type="checkbox" ${isGRTReceived(base)?'disabled checked':''}><b>GRT RECIBIDA</b><small>${isGRTReceived(base)?'Ya registrada anteriormente':'Se marca una sola vez para todo el paquete'}</small></label></div>
      <div class="bulk-box"><div class="section-label">Asignar tipo en grupo</div><p class="muted">Selecciona las filas de la primera columna y luego toca un tipo.</p>${typeButtons('')}</div>
      <div class="package-table-wrap"><table class="package-table"><thead><tr><th><input id="pkgSelectAll" type="checkbox"></th><th>GR cliente</th><th>Pedido</th><th>Tipo</th><th>GR recibida</th><th>Documentos de esta recepción</th></tr></thead><tbody>${group.map(r=>`<tr data-pkg-row="${r.id}"><td><input class="pkgSelect" type="checkbox"></td><td><b>${esc(r.gr)}</b></td><td>${esc(r.order||'—')}</td><td class="pkgType">${r.type?`<span class="type-pill">${esc(r.type)}</span>`:'<span class="muted">Sin asignar</span>'}</td><td class="center"><input class="pkgArrived big-checkbox" type="checkbox"></td><td class="pkgDocs">${packageMiniDocs(r,r.type)}</td></tr>`).join('')}</tbody></table></div>
      <div class="modal-actions"><button class="btn" id="cancelPkg">Cancelar</button><button class="btn primary big" id="savePkg">GUARDAR PAQUETE</button></div>`;
    openModal('Registrar paquete completo', `${group.length} GR relacionadas a ${base.grt}. Asigna tipo y marca únicamente las GR que realmente llegaron.`, html, 'package-modal');
    $('#pkgSelectAll').onchange=e=>$$('.pkgSelect',$('#modalBody')).forEach(c=>c.checked=e.target.checked);
    $$('.type-btn',$('#modalBody')).forEach(btn=>btn.onclick=()=>{
      const sel=$$('.pkgSelect:checked',$('#modalBody')); if(!sel.length){toast('Selecciona primero una o más GR',true);return;}
      sel.forEach(c=>{ const tr=c.closest('tr'), r=getRecord(tr.dataset.pkgRow); r._pkgType=btn.dataset.type; $('.pkgType',tr).innerHTML=`<span class="type-pill">${esc(btn.dataset.type)}</span>`; $('.pkgDocs',tr).innerHTML=packageMiniDocs(r,btn.dataset.type); wirePackageExtra($('.pkgDocs',tr)); c.checked=false; });
      $('#pkgSelectAll').checked=false;
    });
    $$('.pkgDocs',$('#modalBody')).forEach(wirePackageExtra);
    $('#cancelPkg').onclick=()=>{ group.forEach(r=>delete r._pkgType); closeModal(); };
    $('#savePkg').onclick=()=>savePackage(group,base);
  }
  function packageAccumulatedReference(r){
    const hasAny=isGRTReceived(r) || (r.receipts||[]).some(m=>docCount(m.docs)>0) || !!r.facturaState || !!r.ocState;
    if(!hasAny) return '';
    const parts=[];
    const d=sumDocs(r,false);
    if(isGRTReceived(r)) parts.push('GRT recibida');
    if(r.type==='Venta CENARES'){
      parts.push(`GR ${d.grCopies}/4`);
      parts.push(`Actas ${d.actas}/4`);
      parts.push(`Pecosas ${d.pecosas}/4`);
    }else if(d.gr) parts.push('GR recibida');
    if(r.type==='Venta' || r.type==='Venta CENARES'){
      parts.push(`Factura: ${r.facturaState||'Sin definir'}`);
      parts.push(`OC: ${r.ocState||'Sin definir'}`);
    }
    if(d.extras.length) parts.push(`Adicional: ${d.extras.join(', ')}`);
    return `<div class="pkg-accum"><span>YA REGISTRADO</span><strong>${esc(parts.join(' · '))}</strong></div>`;
  }
  function packageMiniDocs(r,type){
    const acc=packageAccumulatedReference(r);
    if(!type) return `${acc}<span class="muted">Asigna un tipo</span>`;
    const extra=`<div class="mini-extra"><input class="pkgExtraInput" placeholder="Adicional (ej. Plantilla)"><button type="button" class="btn tiny-btn pkgAddExtra">Agregar</button><span class="pkgExtraTags"></span></div>`;
    if(SIMPLE_TYPES.includes(type)) return `${acc}<div class="mini-doc-note">La GR nueva se toma de “GR recibida”.</div>${extra}`;
    if(type==='Venta') return `${acc}<div class="mini-states"><label>Factura <select class="pkgFact"><option value="">—</option><option>Recibido</option><option>Pendiente</option><option>No aplica</option></select></label><label>OC <select class="pkgOC"><option value="">—</option><option>Recibido</option><option>Pendiente</option><option>No aplica</option></select></label></div>${extra}`;
    if(type==='Venta CENARES') return `${acc}<div class="mini-counts"><label>GR recibidas <input class="pkgCntGR" type="number" min="0" max="4" value="0"><span class="mini-expected">de 4 esperadas</span></label><label>Actas recibidas <input class="pkgCntAct" type="number" min="0" max="4" value="0"><span class="mini-expected">de 4 esperadas</span></label><label>Pecosas recibidas <input class="pkgCntPec" type="number" min="0" max="4" value="0"><span class="mini-expected">de 4 esperadas</span></label></div><div class="mini-states"><label>Factura <select class="pkgFact"><option value="">—</option><option>Recibido</option><option>Pendiente</option><option>No aplica</option></select></label><label>OC <select class="pkgOC"><option value="">—</option><option>Recibido</option><option>Pendiente</option><option>No aplica</option></select></label></div>${extra}`;
    return acc;
  }
  function wirePackageExtra(root){
    const btn=$('.pkgAddExtra',root); if(!btn || btn.dataset.wired)return; btn.dataset.wired='1'; btn.onclick=()=>{ const input=$('.pkgExtraInput',root), tags=$('.pkgExtraTags',root), v=input.value.trim(); if(!v)return; const s=document.createElement('span'); s.className='extra-tag small'; s.dataset.value=v; s.innerHTML=`${esc(v)} <button type="button">×</button>`; $('button',s).onclick=()=>s.remove(); tags.appendChild(s); input.value=''; };
  }
  function savePackage(group,base){
    const rows=$$('[data-pkg-row]',$('#modalBody')); const arrivedRows=rows.filter(tr=>$('.pkgArrived',tr).checked);
    if(!arrivedRows.length && !$('#pkgGRT').checked){ toast('No has marcado ninguna GR recibida',true); return; }
    const missing=rows.filter(tr=>!$('.pkgArrived',tr).checked).map(tr=>getRecord(tr.dataset.pkgRow).gr);
    if(missing.length){
      const msg=`Paquete incompleto: ${arrivedRows.length} de ${rows.length} GR registradas.\n\nFaltan:\n${missing.join('\n')}\n\nPuedes guardar de todos modos.`;
      if(!confirm(msg)) return;
    }
    const missingTypeRow=arrivedRows.find(tr=>{ const r=getRecord(tr.dataset.pkgRow); return !(r._pkgType||r.type); });
    if(missingTypeRow){ const rr=getRecord(missingTypeRow.dataset.pkgRow); toast(`La GR ${rr.gr} llegó pero no tiene tipo. Asígnale un tipo.`,true); return; }
    const sharedGRTNew = $('#pkgGRT').checked && !isGRTReceived(base);
    if(sharedGRTNew) setGRTReceived(base.grt);
    let grtAssigned=false;
    rows.forEach(tr=>{
      const r=getRecord(tr.dataset.pkgRow); const arrived=$('.pkgArrived',tr).checked; const type=r._pkgType || r.type;
      if(type) r.type=type;
      if(!arrived){ recalc(r); delete r._pkgType; return; }
      const docs={grt:0,gr:0,grCopies:0,actas:0,pecosas:0,factura:0,oc:0,extras:[]};
      if(sharedGRTNew && !grtAssigned){ grtAssigned=true; }
      const area=$('.pkgDocs',tr);
      if(type==='Venta CENARES') docs.grCopies=Math.max(0,Math.min(4,Number($('.pkgCntGR',area)?.value||0))); else docs.gr=1;
      if(type==='Venta CENARES'){ docs.actas=Math.max(0,Math.min(4,Number($('.pkgCntAct',area)?.value||0))); docs.pecosas=Math.max(0,Math.min(4,Number($('.pkgCntPec',area)?.value||0))); }
      const fs=$('.pkgFact',area)?.value||'', os=$('.pkgOC',area)?.value||''; if(fs==='Recibido')docs.factura=1; if(os==='Recibido')docs.oc=1; if(fs)r.facturaState=fs; if(os)r.ocState=os;
      $$('.extra-tag',area).forEach(x=>docs.extras.push(x.dataset.value));
      r.receipts.push({id:uid('rec'),at:nowIso(),user:state.currentUser,docs,sentReportId:null});
      r.audit.push({at:nowIso(),user:state.currentUser,action:'Registro de paquete',detail:docsTextFromRaw(docs)}); recalc(r); delete r._pkgType;
    });
    saveState(); audit('Registro de paquete',`${base.grt}: ${arrivedRows.length}/${rows.length} GR`); closeModal(); $('#quickSearch').value=''; $('#quickResult').classList.add('hidden'); renderAll(); $('#quickSearch').focus(); toast(`Paquete guardado: ${arrivedRows.length}/${rows.length} GR`);
  }

  // ---------- Observaciones / seguimiento ----------
  function latestFollowUp(r){
    const arr=r.followUps||[]; return arr.length?arr[arr.length-1]:null;
  }
  function followUpCell(r){
    const f=latestFollowUp(r);
    if(!f) return `<button class="obs-link empty" data-follow="${r.id}">+ Agregar</button>`;
    const sit=f.situation?`<b>${esc(f.situation)}</b>`:''; const note=f.note?`<span>${esc(f.note)}</span>`:'';
    return `<button class="obs-link" data-follow="${r.id}">${sit}${note}<small>${new Date(f.at).toLocaleDateString('es-PE')}</small></button>`;
  }
  function openFollowUp(r){
    const history=(r.followUps||[]).slice().reverse();
    const hist=history.length?`<div class="follow-history"><h4>Historial</h4>${history.map(x=>`<div class="follow-item"><div><b>${esc(x.situation||'Sin situación')}</b><span>${esc(x.note||'')}</span></div><small>${new Date(x.at).toLocaleString('es-PE')} · ${esc(x.user||'—')}</small></div>`).join('')}</div>`:'<div class="empty-hint">Aún no hay observaciones registradas en el sistema nuevo.</div>';
    const html=`${baseInfo(r)}<div class="form-grid follow-form"><div class="field span2"><label>Situación</label><input id="followSituation" placeholder="Ej. En tránsito a Lima, En custodia, Trámite detenido"></div><div class="field span2"><label>Observación</label><textarea id="followNote" rows="3" placeholder="Escribe la observación actual…"></textarea></div></div>${hist}<div class="modal-actions"><button class="btn" id="followCancel">Cancelar</button><button class="btn primary" id="followSave">Guardar seguimiento</button></div>`;
    openModal('Observaciones / seguimiento','Independiente del Resultado de la guía. Cada actualización queda en el historial.',html,'follow-modal');
    $('#followCancel').onclick=closeModal; $('#followSave').onclick=()=>{
      const situation=$('#followSituation').value.trim(), note=$('#followNote').value.trim();
      if(!situation && !note){toast('Escribe una situación o una observación',true);return;}
      r.followUps=r.followUps||[]; r.followUps.push({id:uid('fol'),at:nowIso(),user:state.currentUser,situation,note}); r.situation=situation; r.observations=note;
      r.audit=r.audit||[]; r.audit.push({at:nowIso(),user:state.currentUser,action:'Seguimiento actualizado',detail:[situation,note].filter(Boolean).join(' · ')});
      saveState(); audit('Seguimiento actualizado',r.gr); closeModal(); renderAll(); toast('Seguimiento guardado');
    };
  }

  // ---------- Pending ----------
  let pendingMode='';
  const selectedDistricts=new Set();
  function districtList(){ return [...new Set(allOperational().map(r=>r.district).filter(Boolean))].sort(); }
  function updateDistrictFilterButton(){
    const btn=$('#districtFilterBtn'); if(!btn)return; const vals=[...selectedDistricts];
    btn.textContent=!vals.length?'Todos':vals.length===1?vals[0]:`${vals.length} seleccionados`;
    btn.title=vals.length?vals.join(' · '):'Todos';
    btn.classList.toggle('has-selection',vals.length>0);
  }
  function renderDistrictFilterOptions(){
    const box=$('#districtFilterOptions'); if(!box)return;
    const q=String($('#districtFilterSearch')?.value||'').trim().toLowerCase();
    const rows=districtList().filter(x=>!q||x.toLowerCase().includes(q));
    box.innerHTML=rows.length?rows.map(x=>`<label class="multi-select-option"><input type="checkbox" value="${esc(x)}" ${selectedDistricts.has(x)?'checked':''}><span>${esc(x)}</span></label>`).join(''):'<div class="multi-select-empty">No se encontraron distritos.</div>';
    updateDistrictFilterButton();
  }
  $$('.stat-filter').forEach(b=>b.onclick=()=>{ pendingMode=b.dataset.pendingFilter; renderPending(); });
  $('#partialAlert').onclick=()=>{ pendingMode='partial'; $('#statusFilter').value='Parcial'; renderPending(); };
  ['pendingSearch','recipientFilter','statusFilter','unsentFilter'].forEach(id=>$('#'+id).addEventListener('input',renderPending));
  $('#districtFilterBtn').onclick=e=>{
    e.stopPropagation(); const menu=$('#districtFilterMenu'); menu.classList.toggle('hidden');
    if(!menu.classList.contains('hidden')){ renderDistrictFilterOptions(); setTimeout(()=>$('#districtFilterSearch')?.focus(),0); }
  };
  $('#districtFilterSearch').addEventListener('input',renderDistrictFilterOptions);
  $('#districtFilterOptions').addEventListener('change',e=>{
    const cb=e.target.closest('input[type=checkbox]'); if(!cb)return;
    if(cb.checked)selectedDistricts.add(cb.value); else selectedDistricts.delete(cb.value);
    updateDistrictFilterButton(); renderPending();
  });
  document.addEventListener('click',e=>{ if(!$('#districtMulti')?.contains(e.target)) $('#districtFilterMenu')?.classList.add('hidden'); });
  $('#clearPendingFilters').onclick=()=>{ pendingMode=''; selectedDistricts.clear(); $('#pendingSearch').value=''; $('#recipientFilter').value=''; $('#districtFilterSearch').value=''; $('#statusFilter').value=''; $('#unsentFilter').value=''; $('#districtFilterMenu').classList.add('hidden'); updateDistrictFilterButton(); renderPending(); };
  function renderPending(){
    recalcAll(); const active=allOperational().filter(r=>!r.liquidated && ['Pendiente','Parcial'].includes(r.result));
    $('#statPending').textContent=active.filter(r=>r.result==='Pendiente').length;
    const partialCount=active.filter(r=>r.result==='Parcial').length;
    const partialUnsent=active.filter(r=>r.result==='Parcial'&&hasUnsent(r)).length;
    $('#statPartial').textContent=partialCount;
    $('#statDecide').textContent=active.filter(r=>r.result==='Parcial'&&hasUnsent(r)&&!r.readyManual).length;
    $('#statUntyped').textContent=active.filter(r=>!r.type).length;
    $('#partialAlertCount').textContent=partialCount;
    $('#partialAlertUnsent').textContent=partialUnsent;
    $('#partialAlert').classList.toggle('hidden',partialCount===0);
    renderDistrictFilterOptions();
    const q=$('#pendingSearch').value.toLowerCase(), recq=$('#recipientFilter').value.toLowerCase(), st=$('#statusFilter').value, uns=$('#unsentFilter').value;
    let rows=active.filter(r=>{
      if(q && ![r.gr,r.grt,r.order].join(' ').toLowerCase().includes(q)) return false;
      if(recq && !String(r.recipient||'').toLowerCase().includes(recq)) return false;
      if(selectedDistricts.size&&!selectedDistricts.has(r.district))return false; if(st&&r.result!==st)return false; if(uns==='yes'&&!hasUnsent(r))return false; if(uns==='no'&&hasUnsent(r))return false;
      if(pendingMode==='pending'&&r.result!=='Pendiente')return false; if(pendingMode==='partial'&&r.result!=='Parcial')return false; if(pendingMode==='decide'&&!(r.result==='Parcial'&&hasUnsent(r)&&!r.readyManual))return false; if(pendingMode==='untyped'&&r.type)return false; return true;
    });
    $('#pendingTableBody').innerHTML=rows.slice(0,300).map(r=>`<tr><td>${fmtDate(r.guideDate)}</td><td>${esc(r.district)}</td><td>${esc(r.grt)}</td><td><b>${esc(r.gr)}</b></td><td>${esc(r.order)}</td><td>${esc(r.recipient)}</td><td class="address-cell">${esc(r.address||'—')}</td><td>${r.type?`<span class="type-pill">${esc(r.type)}</span>`:'<span class="status warning">Sin tipificar</span>'}</td><td><span class="status ${r.result.toLowerCase()}">${esc(r.result)}</span></td><td>${esc(docsText(r,false))}</td><td>${hasUnsent(r)?'<span class="yes-pill">Sí</span>':'No'}</td><td class="obs-cell-wrap">${followUpCell(r)}</td><td class="actions-cell"><button class="btn small" data-add="${r.id}">Agregar docs</button>${r.result==='Parcial'&&hasUnsent(r)&&!r.readyManual?`<button class="btn small primary" data-ready="${r.id}">Enviar parcial</button>`:''}${r.result==='Parcial'?`<button class="btn small" data-complete="${r.id}">Completar</button>`:''}<button class="icon-btn" data-view="${r.id}">🔍</button></td></tr>`).join('') || '<tr><td colspan="13" class="empty-row">No hay registros con estos filtros.</td></tr>';
    $$('[data-add]').forEach(b=>b.onclick=()=>openSingleRegistration(getRecord(b.dataset.add),'add'));
    $$('[data-ready]').forEach(b=>b.onclick=()=>{const r=getRecord(b.dataset.ready);r.readyManual=true;r.audit.push({at:nowIso(),user:state.currentUser,action:'Marcado listo para enviar',detail:'Envío parcial'});saveState();audit('Parcial listo para enviar',r.gr);renderAll();toast('Parcial enviado a Listos para enviar');});
    $$('[data-complete]').forEach(b=>b.onclick=()=>manualComplete(getRecord(b.dataset.complete)));
    $$('[data-view]').forEach(b=>b.onclick=()=>openDetail(getRecord(b.dataset.view)));
    $$('[data-follow]').forEach(b=>b.onclick=()=>openFollowUp(getRecord(b.dataset.follow)));
  }
  function manualComplete(r){
    if(hasUnsent(r)){
      if(!confirm('Esta GR tiene documentos recibidos por enviar. Al completar manualmente pasará a Listos para enviar. ¿Continuar?'))return;
      r.manualComplete=true; recalc(r); saveState(); audit('Completo manual',r.gr); renderAll(); toast('Marcada Completa y lista para enviar');
    }else{
      const reason=prompt('No existen documentos nuevos por enviar. Para liquidar directamente, indica el motivo obligatorio:'); if(!reason?.trim())return;
      r.manualComplete=true; r.result='Completo'; r.liquidated=true; r.liquidatedAt=nowIso(); r.closeReason=reason.trim(); r.audit.push({at:nowIso(),user:state.currentUser,action:'Liquidación directa',detail:reason.trim()}); saveState(); audit('Liquidación directa',`${r.gr}: ${reason.trim()}`); renderAll(); toast('GR liquidada sin generar reporte vacío');
    }
  }

  // ---------- Detail ----------
  function detailReceiptRows(r){
    const group=groupFor(r), shared=group.length>1, ledger=getGRTLedger(r.grt);
    const events=(r.receipts||[]).map(m=>({at:m.at,user:m.user,docs:docsTextFromRaw(m.docs),sentReportId:m.sentReportId,receipt:m}));
    if(ledger && !shared){
      let nearest=null, best=Infinity;
      events.forEach(e=>{ const diff=Math.abs(new Date(e.at)-new Date(ledger.at)); if(diff<best){best=diff;nearest=e;} });
      if(nearest && best<=30000){
        nearest.docs = nearest.docs==='Sin documentos físicos' ? 'GRT' : `GRT + ${nearest.docs}`;
        if(!nearest.sentReportId && ledger.sentReportId) nearest.sentReportId=ledger.sentReportId;
      }else{
        events.push({at:ledger.at,user:ledger.user||'—',docs:'GRT',sentReportId:ledger.sentReportId||null});
      }
    }
    events.sort((a,b)=>new Date(a.at)-new Date(b.at));
    return events.map(e=>`<tr><td>${new Date(e.at).toLocaleString('es-PE')}</td><td>${esc(e.user)}</td><td>${esc(e.docs)}</td><td>${e.sentReportId?esc(reportLabel(e.sentReportId)):'Pendiente de envío'}</td></tr>`).join('');
  }
  function sharedGRTDetail(r){
    const group=groupFor(r), ledger=getGRTLedger(r.grt);
    if(group.length<=1 || !ledger) return '';
    return `<div class="shared-grt-detail"><b>GRT compartida ${esc(r.grt)} recibida para este paquete</b><span>${new Date(ledger.at).toLocaleString('es-PE')} · ${esc(ledger.user||'—')} · ${ledger.sentReportId?'Enviada en '+esc(reportLabel(ledger.sentReportId)):'Aún no enviada'}</span></div>`;
  }
  function openDetail(r){
    const receipts=detailReceiptRows(r);
    const follow=(r.followUps||[]).slice().reverse();
    const followHtml=follow.length?`<div class="table-wrap"><table><thead><tr><th>Fecha/hora</th><th>Situación</th><th>Observación</th><th>Usuario</th></tr></thead><tbody>${follow.map(x=>`<tr><td>${new Date(x.at).toLocaleString('es-PE')}</td><td>${esc(x.situation||'—')}</td><td>${esc(x.note||'—')}</td><td>${esc(x.user||'—')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-hint">Sin observaciones registradas en el sistema nuevo.</div>';
    const gh=(r.grtHistory||[]).slice().reverse();
    const grtHist=gh.length?`<div class="grt-history"><h4>Historial de GRT</h4>${gh.map(x=>`<div><b>${esc(x.oldGRT||'—')} → ${esc(x.newGRT||r.grt)}</b><span>${x.at?new Date(x.at).toLocaleString('es-PE'):'Migración inicial'} · ${esc(x.user||'—')} · ${esc(x.reason||'')}</span></div>`).join('')}</div>`:'';
    const html=`${baseInfo(r)}<div class="detail-kpis"><div><span>Tipo</span><b>${esc(r.type||'Sin tipificar')}</b></div><div><span>Resultado</span><b>${esc(r.result)}</b></div><div><span>Docs por enviar</span><b>${hasUnsent(r)?'Sí':'No'}</b></div><div><span>Documentación acumulada</span><b>${esc(docsText(r,false))}</b></div></div>${sharedGRTDetail(r)}${grtHist}${r.closeReason?`<div class="callout">Liquidación directa: ${esc(r.closeReason)}</div>`:''}<h4>Historial de recepciones</h4><div class="table-wrap"><table><thead><tr><th>Fecha/hora</th><th>Usuario</th><th>Documentos</th><th>Envío</th></tr></thead><tbody>${receipts||'<tr><td colspan="4">Sin recepciones</td></tr>'}</tbody></table></div><div class="detail-section-head"><h4>Observaciones / seguimiento</h4><button class="btn small" id="detailAddFollow">Actualizar seguimiento</button></div>${followHtml}`;
    openModal('Detalle de guía','Solo lectura para documentos. El seguimiento se registra desde su botón.',html,'detail-modal');
    $('#detailAddFollow').onclick=()=>{ closeModal(); openFollowUp(r); };
  }
  function reportLabel(id){ const rp=state.reports.find(x=>x.id===id); return rp?rp.cargo:id; }

  function nextCargoFrom(cargo){
    const raw=String(cargo||'').trim();
    const m=raw.match(/^(.*?)(\d+)$/);
    if(!m) return '';
    const n=String(Number(m[2])+1).padStart(m[2].length,'0');
    return `${m[1]}${n}`;
  }
  function nextNewCargo(){
    if(!state.reports.length) return state.settings?.cargoStart||'';
    return nextCargoFrom(state.reports[state.reports.length-1].cargo);
  }
  function syncCargoField(){
    const input=$('#cargoNumber'); if(!input) return;
    if(state.reports.length){ input.value=nextNewCargo(); input.readOnly=true; input.title='Correlativo automático para un reporte nuevo'; }
    else { input.readOnly=false; if(!input.value && state.settings?.cargoStart) input.value=state.settings.cargoStart; input.title='Indica el primer correlativo de esta prueba'; }
  }

  // ---------- Ready / report ----------
  $('#selectAllReadyBtn').onclick=()=>$$('.readyCheck').forEach(x=>x.checked=true);
  $('#clearReadyBtn').onclick=()=>$$('.readyCheck').forEach(x=>x.checked=false);
  $('#previewReportBtn').onclick=previewReport;
  function renderReady(){
    syncCargoField();
    recalcAll(); const rows=allOperational().filter(isReady);
    $('#readyTableBody').innerHTML=rows.map(r=>`<tr><td><input class="readyCheck big-checkbox" type="checkbox" value="${r.id}" checked></td><td><b>${esc(r.gr)}</b></td><td>${esc(r.grt)}</td><td>${esc(r.order)}</td><td>${esc(r.recipient)}</td><td>${esc(r.type)}</td><td><span class="status ${r.result.toLowerCase()}">${esc(r.result)}</span></td><td>${esc(docsText(r,true))}</td><td><button class="icon-btn" data-view-ready="${r.id}">🔍</button></td></tr>`).join('')||'<tr><td colspan="9" class="empty-row">No hay guías listas para enviar.</td></tr>';
    $$('[data-view-ready]').forEach(b=>b.onclick=()=>openDetail(getRecord(b.dataset.viewReady)));
  }
  function previewReport(){
    const ids=$$('.readyCheck:checked').map(x=>Number(x.value)); if(!ids.length){toast('Selecciona al menos una GR',true);return;}
    const date=$('#reportDate').value; if(!date){toast('Selecciona la fecha de entrega a Roche',true);return;}
    const cargo=$('#cargoNumber').value.trim(); if(!cargo){toast('Indica el primer CARGO para esta prueba',true);return;}
    if(state.reports.some(r=>String(r.cargo).toLowerCase()===cargo.toLowerCase())){toast('Ese CARGO ya existe. Un reporte nuevo debe usar el siguiente correlativo.',true);return;}
    if(!state.reports.length){ state.settings=state.settings||{}; state.settings.cargoStart=cargo; saveState(); }
    state.reportDraft={ids,date,cargo}; showReportPreview(state.reportDraft,false);
  }
  function showReportPreview(draft, correction=false, report=null){
    const rows=draft.ids.map(id=>getRecord(id)).filter(Boolean);
    const previewCarrier={}; rows.forEach(r=>{if(grtUnsent(r.grt) && previewCarrier[r.grt]==null) previewCarrier[r.grt]=r.id;});
    const snapshotMap=new Map();
    if(correction && report) currentReportItems(report).forEach(it=>snapshotMap.set(String(it.recordId),it));
    const html=`<div class="report-meta"><div><span>CARGO</span><b>${esc(draft.cargo)}</b></div><div><span>FECHA</span><b>${fmtDate(draft.date)}</b></div><div><span>PARA</span><b>DIEGO</b></div></div><div class="callout">${correction?'Estás viendo exactamente el contenido de la versión vigente. Desmarca solo lo que deseas retirar del cargo.':'Puedes desmarcar una GR. Al hacerlo queda fuera de este cargo, pero conserva su Resultado y su condición de Lista para enviar.'}</div><div class="table-wrap"><table><thead><tr><th>Enviar</th><th>GR</th><th>GRT</th><th>Pedido</th><th>Tipo</th><th>Resultado</th><th>OBS DE CONFORMIDAD</th></tr></thead><tbody>${rows.map(r=>{const snap=snapshotMap.get(String(r.id)); const obs=correction&&snap?snap.obs:batchObs(r,previewCarrier[r.grt]===r.id); const result=correction&&snap?(snap.resultAtSend||r.result):r.result; return `<tr><td><input class="previewCheck big-checkbox" type="checkbox" value="${r.id}" checked></td><td><b>${esc(r.gr)}</b></td><td>${esc(r.grt)}</td><td>${esc(r.order)}</td><td>${esc(r.type)}</td><td>${esc(result)}</td><td>${esc(obs)}</td></tr>`;}).join('')}</tbody></table></div><div class="modal-actions"><button class="btn" id="backPreview">Volver</button><button class="btn primary big" id="confirmReport">${correction?'GUARDAR CORRECCIÓN Y CONFIRMAR':'CONFIRMAR REPORTE'}</button></div>`;
    openModal(correction?'Corregir reporte':'Vista previa del reporte',correction?'Mismo CARGO. La versión anterior quedará disponible en Historial de versiones.':'Nada cambia definitivamente hasta confirmar.',html,'report-modal');
    $('#backPreview').onclick=closeModal;
    $('#confirmReport').onclick=()=>{
      const ids=$$('.previewCheck:checked').map(x=>Number(x.value)); if(!ids.length){toast('El reporte no puede quedar vacío',true);return;}
      if(correction) confirmCorrection(report,ids,draft); else confirmNewReport(ids,draft);
    };
  }
  function latestReceiptDateForBatch(r, includeGRT=false){
    const arr=(r.receipts||[]).filter(m=>!m.sentReportId && docCount(m.docs)>0).map(m=>m.at);
    if(includeGRT){ const g=getGRTLedger(r.grt); if(g && !g.sentReportId) arr.push(g.at); }
    arr.sort(); return arr.length?arr[arr.length-1]:nowIso();
  }
  function batchObs(r, includeGRT=false){
    const d=sumDocs(r,true), parts=[];
    if(includeGRT) parts.push('grt');
    if(r.type==='Venta CENARES'){
      if(d.grCopies) parts.push(`${d.grCopies} gr`);
      if(d.actas) parts.push(`${d.actas} Actas`);
      if(d.pecosas) parts.push(`${d.pecosas} Pecosas`);
    }else if(d.gr) parts.push('gr');
    if(d.factura) parts.push('fact');
    if(d.oc) parts.push('oc');
    d.extras.forEach(x=>parts.push(x));
    return parts.join(' + ') || '—';
  }
  function buildBatchItems(ids,reportId,date){
    const records=ids.map(id=>getRecord(id)).filter(Boolean);
    const carrierByGRT={};
    records.forEach(r=>{ if(grtUnsent(r.grt) && carrierByGRT[r.grt]==null) carrierByGRT[r.grt]=r.id; });
    return records.map(r=>{
      const includeGRT=carrierByGRT[r.grt]===r.id;
      const receiptIds=(r.receipts||[]).filter(m=>!m.sentReportId && docCount(m.docs)>0).map(m=>m.id);
      return {recordId:r.id,gr:r.gr,grt:r.grt,order:r.order,recipient:r.recipient,district:r.district,route:r.route,guideDate:r.guideDate,type:r.type,resultAtSend:r.result,obs:batchObs(r,includeGRT),includeGRT,receiptIds,acuse:latestReceiptDateForBatch(r,includeGRT),deliveryDate:date};
    });
  }
  function confirmNewReport(ids,draft){
    const report={id:uid('rep'),cargo:draft.cargo,date:draft.date,to:'DIEGO',status:'Vigente',currentVersion:1,versions:[]};
    const items=buildBatchItems(ids,report.id,draft.date);
    report.versions.push({version:1,at:nowIso(),user:state.currentUser,reason:'Emisión inicial',items:deepClone(items),status:'Vigente'});
    state.reports.push(report);
    items.forEach(it=>applyReportItemToRecord(getRecord(it.recordId),report.id,it));
    saveState(); audit('Reporte Roche confirmado',`${report.cargo} · ${ids.length} GR`); closeModal(); renderAll(); downloadReportXlsx(report); toast(`${report.cargo} confirmado y Excel generado`);
  }
  function applyReportItemToRecord(r,reportId,item){
    const ids=new Set(item.receiptIds||[]);
    if(ids.size){ (r.receipts||[]).forEach(m=>{if(ids.has(m.id))m.sentReportId=reportId;}); }
    else { (r.receipts||[]).forEach(m=>{if(!m.sentReportId && docCount(m.docs)>0)m.sentReportId=reportId;}); }
    if(item.includeGRT){ const g=getGRTLedger(r.grt); if(g&&!g.sentReportId)g.sentReportId=reportId; }
    recalc(r);
    if(r.result==='Completo'){r.liquidated=true;r.liquidatedAt=nowIso();r.readyManual=false;} else if(r.result==='Parcial'){r.readyManual=false;}
    r.audit.push({at:nowIso(),user:state.currentUser,action:'Incluida en reporte Roche',detail:reportLabel(reportId)});
  }
  function currentReportItems(report){ return report.versions.find(v=>v.version===report.currentVersion)?.items||[]; }
  function getReportVersion(report,version){ return report.versions.find(v=>Number(v.version)===Number(version))||null; }
  function confirmCorrection(report,newIds,draft){
    const reason=prompt('Motivo de la corrección (obligatorio):'); if(!reason?.trim())return;
    const oldItems=currentReportItems(report); const oldIds=oldItems.map(x=>x.recordId);
    oldItems.forEach(it=>{
      const r=getRecord(it.recordId); if(!r)return;
      const ids=new Set(it.receiptIds||[]);
      (r.receipts||[]).forEach(m=>{ if((ids.size&&ids.has(m.id)) || (!ids.size&&m.sentReportId===report.id)){ if(m.sentReportId===report.id)m.sentReportId=null; } });
      const g=getGRTLedger(r.grt); if(it.includeGRT && g&&g.sentReportId===report.id)g.sentReportId=null;
      if(r.liquidated){r.liquidated=false;r.liquidatedAt='';}
      recalc(r);
    });
    const wanted=new Set(newIds.map(String));
    const newItems=deepClone(oldItems.filter(it=>wanted.has(String(it.recordId))));
    newItems.forEach(it=>applyReportItemToRecord(getRecord(it.recordId),report.id,it));
    report.versions.forEach(v=>{if(v.status==='Vigente')v.status='Corregida';});
    report.currentVersion+=1; report.date=draft.date;
    report.versions.push({version:report.currentVersion,at:nowIso(),user:state.currentUser,reason:reason.trim(),items:deepClone(newItems),status:'Vigente'});
    const removed=oldIds.filter(id=>!wanted.has(String(id))); removed.forEach(id=>{const r=getRecord(id); if(!r)return; recalc(r); if(r.result==='Parcial')r.readyManual=true;});
    saveState(); audit('Corrección de reporte Roche',`${report.cargo} · v${report.currentVersion} · ${reason.trim()}`); closeModal(); renderAll(); downloadReportXlsx(report); toast(`${report.cargo} corregido. Se mantiene el mismo correlativo.`);
  }

  // ---------- XLSX generator (valid Roche template + JSZip) ----------
  // V1.4.3: instead of hand-crafting an XLSX package from zero, we start from the
  // real Roche workbook supplied by the user, replace only the worksheet data, and
  // let JSZip rebuild the Office package. This keeps the original logo/styles/theme
  // and avoids Excel's "repair workbook" warning.
  function xxml(s){
    return String(s??'')
      .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\uFFFE\uFFFF]/g,'')
      .replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
  }
  function xlsxInlineCell(ref,val,style=0){
    return `<c r="${ref}" t="inlineStr" s="${style}"><is><t xml:space="preserve">${xxml(val)}</t></is></c>`;
  }
  function buildRocheSheetXml(report, versionObj=null){
    const items=versionObj?versionObj.items:currentReportItems(report);
    const reportDate=(items[0]&&items[0].deliveryDate)||report.date;
    const rows=[];

    // Header positions and style IDs are taken from the real 16-09 Roche workbook.
    rows.push(`<row r="1" spans="1:11" ht="22.5" customHeight="1" x14ac:dyDescent="0.3">${xlsxInlineCell('E1','FORMATO DE RETORNO DE CARGOS A SIGNIA - ROCHE',11)}${xlsxInlineCell('J1',`CARGO: ${report.cargo}`,3)}${xlsxInlineCell('K1',`FECHA: ${fmtShort(reportDate)}`,16)}</row>`);
    rows.push(`<row r="2" spans="1:11" ht="22.5" customHeight="1" x14ac:dyDescent="0.3">${xlsxInlineCell('K2','PARA: DIEGO',17)}</row>`);
    rows.push(`<row r="3" spans="1:11" ht="21" customHeight="1" x14ac:dyDescent="0.25"></row>`);

    const headers=[
      ['A4','ACUSE\nRECIBIDO',8],['B4','FECHA GUIA',8],['C4','DISTRITO',8],
      ['D4','HOJA DE\nRUTA',18],['E4','NUMERO DE\nPEDIDO',18],['F4','DESTINATARIO',9],
      ['G4','GR TRADEL',19],['H4','GUIA CLIENTE',9],['I4','TIPO',9],
      ['J4','OBS DE CONFORMIDAD\nDocumentacion',9],['K4','FECHA\nENTREGA',10]
    ];
    rows.push(`<row r="4" spans="1:11" ht="34.5" customHeight="1" x14ac:dyDescent="0.25">${headers.map(([r,v,st])=>xlsxInlineCell(r,v,st)).join('')}</row>`);

    items.forEach((it,idx)=>{
      const rr=5+idx;
      const odd=(idx%2===0);
      const stDate=odd?20:23, stText=odd?21:24, stOrder=odd?22:25, stGuide=odd?29:30;
      const vals=[fmtShort(it.acuse),fmtShort(it.guideDate),it.district,it.route,it.order,it.recipient,it.grt,it.gr,it.type,it.obs,fmtShort(reportDate)];
      const styles=[stDate,stDate,stText,stText,stOrder,stText,stText,stGuide,stText,stText,stDate];
      const height=String(it.obs||'').length>65?34:23;
      rows.push(`<row r="${rr}" spans="1:11" ht="${height}" customHeight="1" x14ac:dyDescent="0.25">${vals.map((v,i)=>xlsxInlineCell(String.fromCharCode(65+i)+rr,v,styles[i])).join('')}</row>`);
    });

    const lastRow=Math.max(4,4+items.length);
    const widths=[12,13,26,10,13,33,14,18,24,34,18];
    const cols=widths.map((w,i)=>`<col min="${i+1}" max="${i+1}" width="${w}" customWidth="1"/>`).join('');
    return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:mc="http://schemas.openxmlformats.org/markup-compatibility/2006" mc:Ignorable="x14ac" xmlns:x14ac="http://schemas.microsoft.com/office/spreadsheetml/2009/9/ac">
<sheetPr><pageSetUpPr fitToPage="1"/></sheetPr>
<dimension ref="A1:K${lastRow}"/>
<sheetViews><sheetView tabSelected="1" zoomScale="85" zoomScaleNormal="85" workbookViewId="0"><selection activeCell="A5" sqref="A5"/></sheetView></sheetViews>
<sheetFormatPr baseColWidth="10" defaultRowHeight="15" x14ac:dyDescent="0.25"/>
<cols>${cols}</cols>
<sheetData>${rows.join('')}</sheetData>
<autoFilter ref="A4:K${lastRow}"/>
<pageMargins left="0.7" right="0.7" top="0.75" bottom="0.75" header="0.3" footer="0.3"/>
<pageSetup paperSize="9" scale="63" fitToHeight="0" orientation="landscape" r:id="rId1"/>
<drawing r:id="rId2"/>
</worksheet>`;
  }
  async function buildReportXlsx(report, versionObj=null){
    if(typeof JSZip==='undefined') throw new Error('No se encontró el generador ZIP local.');
    if(!window.ROCHE_REPORT_TEMPLATE_BASE64) throw new Error('No se encontró la plantilla Roche.');
    const zip=await JSZip.loadAsync(window.ROCHE_REPORT_TEMPLATE_BASE64,{base64:true,checkCRC32:true});
    zip.file('xl/worksheets/sheet1.xml',buildRocheSheetXml(report,versionObj));
    return await zip.generateAsync({type:'uint8array',compression:'DEFLATE',compressionOptions:{level:6},platform:'DOS'});
  }
  async function downloadReportXlsx(report, versionObj=null){
    if(!report)return;
    try{
      const bytes=await buildReportXlsx(report,versionObj);
      const blob=new Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});
      const url=URL.createObjectURL(blob), a=document.createElement('a');
      const suffix=versionObj?`_v${versionObj.version}`:'';
      a.href=url; a.download=`${report.cargo}${suffix}_RETORNO_ROCHE.xlsx`;
      document.body.appendChild(a); a.click(); a.remove();
      setTimeout(()=>URL.revokeObjectURL(url),3000);
    }catch(err){
      console.error('Error generando Excel Roche',err);
      alert(`No se pudo generar el Excel Roche. El reporte sigue guardado en Historial.\n\n${err?.message||err}`);
    }
  }

  // ---------- General / closed ----------
  let generalState='';
  $$('#generalSegments button').forEach(b=>b.onclick=()=>{ generalState=b.dataset.state; $$('#generalSegments button').forEach(x=>x.classList.toggle('active',x===b)); renderGeneral(); });
  $('#generalSearch').addEventListener('input',renderGeneral);
  function renderGeneral(){
    recalcAll(); const q=$('#generalSearch').value.toLowerCase(); let rows=state.records.filter(r=>r.imported).filter(r=>!q||[r.gr,r.grt,r.order,r.recipient].join(' ').toLowerCase().includes(q));
    if(generalState==='active')rows=rows.filter(r=>!r.cancelled&&!r.liquidated); if(generalState==='liquidated')rows=rows.filter(r=>r.liquidated); if(generalState==='cancelled')rows=rows.filter(r=>r.cancelled);
    $('#generalTableBody').innerHTML=rows.slice(0,400).map(r=>`<tr><td>${fmtDate(r.guideDate)}</td><td>${esc(r.district)}</td><td>${esc(r.route)}</td><td>${esc(r.order)}</td><td>${esc(r.recipient)}</td><td class="address-cell">${esc(r.address||'—')}</td><td>${esc(r.grt)}</td><td><b>${esc(r.gr)}</b></td><td>${esc(r.type||'—')}</td><td>${esc(r.result)}</td><td>${r.cancelled?'Anulado':r.liquidated?'Liquidado':'Activo'}</td><td>${esc(docsText(r,false))}</td><td>${hasUnsent(r)?'Sí':'No'}</td><td>${followUpCell(r)}</td><td><button class="icon-btn" data-gview="${r.id}">🔍</button></td></tr>`).join('');
    $$('[data-gview]').forEach(b=>b.onclick=()=>openDetail(getRecord(b.dataset.gview)));
    $$('[data-follow]', $('#generalTableBody')).forEach(b=>b.onclick=()=>openFollowUp(getRecord(b.dataset.follow)));
  }
  function renderClosed(){
    const rows=state.records.filter(r=>r.liquidated&&!r.cancelled); $('#closedTableBody').innerHTML=rows.map(r=>{const reps=state.reports.filter(p=>currentReportItems(p).some(i=>i.recordId===r.id)); return `<tr><td>${fmtDate(r.liquidatedAt)}</td><td>${esc(r.grt)}</td><td><b>${esc(r.gr)}</b></td><td>${esc(r.order)}</td><td>${esc(r.recipient)}</td><td>${esc(r.address)}</td><td>${esc(r.district)}</td><td>${esc(r.type)}</td><td>${esc(docsText(r,false))}</td><td>${reps.length?esc(reps[reps.length-1].cargo):'Cierre directo'}</td><td><button class="icon-btn" data-cview="${r.id}">🔍</button></td></tr>`;}).join('')||'<tr><td colspan="11" class="empty-row">Aún no hay liquidados.</td></tr>';
    $$('[data-cview]').forEach(b=>b.onclick=()=>openDetail(getRecord(b.dataset.cview)));
  }

  // ---------- History / correction ----------
  function renderHistory(){
    $('#historyTableBody').innerHTML=state.reports.slice().reverse().map(r=>`<tr><td><b>${esc(r.cargo)}</b></td><td>${fmtDate(r.date)}</td><td>v${r.currentVersion}</td><td>${currentReportItems(r).length}</td><td>${esc(r.versions[r.versions.length-1].user)}</td><td>${esc(r.status)}</td><td><button class="btn small" data-hview="${r.id}">Ver</button><button class="btn small" data-download="${r.id}">Descargar</button><button class="btn small" data-correct="${r.id}">Corregir reporte</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty-row">No hay reportes confirmados.</td></tr>';
    $$('[data-hview]').forEach(b=>b.onclick=()=>showHistoryDetail(state.reports.find(x=>x.id===b.dataset.hview)));
    $$('[data-download]').forEach(b=>b.onclick=()=>downloadReportXlsx(state.reports.find(x=>x.id===b.dataset.download)));
    $$('[data-correct]').forEach(b=>b.onclick=()=>startCorrection(state.reports.find(x=>x.id===b.dataset.correct)));
  }
  function showHistoryDetail(r){
    const d=$('#historyDetail'); d.classList.remove('hidden'); d.innerHTML=`<div class="section-head"><div><div class="eyebrow">${esc(r.cargo)}</div><h3>Historial de versiones</h3></div></div>${r.versions.slice().reverse().map(v=>`<div class="version-card"><div><b>Versión ${v.version}</b> <span class="status ${v.status==='Vigente'?'completo':'warning'}">${v.status}</span><br><small>${new Date(v.at).toLocaleString('es-PE')} · ${esc(v.user)} · ${esc(v.reason)}</small></div><div class="version-actions"><strong>${v.items.length} GR</strong><button class="btn small" data-version-view="${v.version}">Ver contenido</button><button class="btn small" data-version-download="${v.version}">Descargar Excel</button></div></div>`).join('')}`;
    $$('[data-version-view]',d).forEach(b=>b.onclick=()=>showReportVersionPreview(r,getReportVersion(r,b.dataset.version)));
    $$('[data-version-download]',d).forEach(b=>b.onclick=()=>downloadReportXlsx(r,getReportVersion(r,b.dataset.version)));
  }
  function showReportVersionPreview(report,versionObj){
    if(!versionObj)return;
    const date=(versionObj.items[0]&&versionObj.items[0].deliveryDate)||report.date;
    const rows=versionObj.items.map(it=>`<tr><td><b>${esc(it.gr)}</b></td><td>${esc(it.grt)}</td><td>${esc(it.order)}</td><td>${esc(it.type)}</td><td>${esc(it.resultAtSend||'—')}</td><td>${esc(it.obs||'—')}</td></tr>`).join('');
    const html=`<div class="report-meta"><div><span>CARGO</span><b>${esc(report.cargo)}</b></div><div><span>VERSIÓN</span><b>v${versionObj.version} · ${esc(versionObj.status)}</b></div><div><span>FECHA</span><b>${fmtDate(date)}</b></div></div><div class="callout">Vista histórica de solo lectura. Este contenido queda conservado aunque exista una versión corregida.</div><div class="table-wrap"><table><thead><tr><th>GR</th><th>GRT</th><th>Pedido</th><th>Tipo</th><th>Resultado al enviar</th><th>OBS DE CONFORMIDAD</th></tr></thead><tbody>${rows}</tbody></table></div><div class="modal-actions"><button class="btn" id="closeVersionPreview">Cerrar</button><button class="btn primary" id="downloadVersionPreview">Descargar esta versión</button></div>`;
    openModal(`Contenido ${report.cargo} · v${versionObj.version}`,`${new Date(versionObj.at).toLocaleString('es-PE')} · ${versionObj.user} · ${versionObj.reason}`,html,'report-modal');
    $('#closeVersionPreview').onclick=closeModal; $('#downloadVersionPreview').onclick=()=>downloadReportXlsx(report,versionObj);
  }
  function startCorrection(report){
    const ids=currentReportItems(report).map(x=>x.recordId); const draft={ids,date:report.date,cargo:report.cargo}; showReportPreview(draft,true,report);
  }

  // ---------- Import / review ----------
  let pendingImport=null;

  function headerKey(v=''){
    return String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z0-9]/g,'');
  }
  function objVal(row, aliases){
    const keys=Object.keys(row||{}); const wanted=aliases.map(headerKey);
    const k=keys.find(x=>wanted.includes(headerKey(x))); return k?row[k]:'';
  }
  function normalizeGR(raw){
    let s=String(raw||'').toUpperCase().trim().replace(/[–—]/g,'-').replace(/\s+/g,'');
    s=s.replace(/^RECEG07-?/,'EG07-').replace(/^RECT002-?/,'T002-').replace(/^RECT006-?/,'T006-').replace(/^REC(?=(T\d{3}|EG\d{2})-)/,'');
    s=s.replace(/^DEVT/,'DEV-T');
    const m=s.match(/^(DEV-)?(T\d{3}|EG\d{2})-?0*(\d+)$/);
    if(!m) return s;
    const prefix=(m[1]||'')+m[2], num=m[3].slice(-8).padStart(8,'0');
    return `${prefix}-${num}`;
  }
  function splitGuideCell(v){
    if(v===null||v===undefined||v==='')return [];
    const s=String(v).toUpperCase();
    let hits=s.match(/(?:DEV-?T\d{3}|T\d{3}|EG\d{2})\s*-\s*\d+/g)||[];
    if(!hits.length) hits=s.split(/[,;\n/]+/).map(x=>x.trim()).filter(Boolean);
    const out=[]; hits.forEach(x=>{const g=normalizeGR(x); if(g&&!out.includes(g))out.push(g);}); return out;
  }
  function valueDateIso(v){
    if(v instanceof Date && !isNaN(v)) return v.toISOString().slice(0,10);
    if(typeof v==='number' && isFinite(v)){ const d=new Date(Date.UTC(1899,11,30)); d.setUTCDate(d.getUTCDate()+Math.floor(v)); return d.toISOString().slice(0,10); }
    const s=String(v||'').trim(); if(!s)return '';
    const iso=s.match(/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})/); if(iso)return `${iso[1]}-${String(iso[2]).padStart(2,'0')}-${String(iso[3]).padStart(2,'0')}`;
    const dm=s.match(/^(\d{1,2})[-/](\d{1,2})[-/](\d{4})/); if(dm)return `${dm[3]}-${String(dm[2]).padStart(2,'0')}-${String(dm[1]).padStart(2,'0')}`;
    return '';
  }
  function cleanNumericText(v){
    const s=String(v??'').trim(); if(/^0*\d+$/.test(s) && s!=='') return String(Number(s)); return s;
  }
  function nextDayIso(iso){
    if(!iso)return ''; const d=new Date(iso+'T12:00:00Z'); d.setUTCDate(d.getUTCDate()+1); return d.toISOString().slice(0,10);
  }
  function maxLoadedGuideDate(){
    return [...state.records,...state.review].map(r=>r.guideDate).filter(Boolean).sort().pop()||'';
  }
  function blankImportedRecord(x){
    return {
      ...deepClone(x), id:uid('gr'), imported:true, type:'', result:'Pendiente', manualComplete:false,
      readyManual:false, cancelled:false, liquidated:false, liquidatedAt:'', closeReason:'', observations:'', situation:'', followUps:[],
      extraNotes:[], receipts:[], audit:[], grtHistory:[], cenExpected:{gr:4,actas:4,pecosas:4}, reviewResolved:!(x.issues||[]).length
    };
  }
  function parseImportWorkbook(file){
    return file.arrayBuffer().then(buf=>{
      if(typeof XLSX==='undefined') throw new Error('No se pudo cargar el lector de Excel. Verifica la conexión a internet e inténtalo otra vez.');
      const wb=XLSX.read(buf,{type:'array',cellDates:true});
      if(wb.SheetNames.length<2) throw new Error('El archivo debe contener al menos dos pestañas: Tradel y Roche.');
      const sheets=wb.SheetNames.map(name=>({name,rows:XLSX.utils.sheet_to_json(wb.Sheets[name],{defval:'',raw:true})}));
      const tradelSheet=sheets.find(s=>s.rows.length && Object.keys(s.rows[0]).some(k=>headerKey(k)==='GUIACLIENTE') && Object.keys(s.rows[0]).some(k=>headerKey(k)==='GRTRADEL')) || sheets[0];
      const rocheSheet=sheets.find(s=>s!==tradelSheet && s.rows.length && Object.keys(s.rows[0]).some(k=>headerKey(k)==='DOCUMENTO') && Object.keys(s.rows[0]).some(k=>headerKey(k)==='NROPEDIDO')) || sheets[1];

      const tradelAll=[];
      tradelSheet.rows.forEach((row,idx)=>{
        const grCell=objVal(row,['GUIA CLIENTE','GUIA CLIENTE ','GUÍA CLIENTE']);
        splitGuideCell(grCell).forEach(gr=>tradelAll.push({
          sourceRow:idx+2, gr, grRaw:String(grCell||''), guideDate:valueDateIso(objVal(row,['FECHA GUIA','FECHA GUÍA'])), district:String(objVal(row,['DISTRITO'])||'').trim(),
          recipient:String(objVal(row,['DESTINATARIO'])||'').trim(), address:String(objVal(row,['DIRECCION','DIRECCIÓN'])||'').trim(), grt:String(objVal(row,['GR TRADEL'])||'').trim(),
          sourceCargoType:String(objVal(row,['TIPO DE CARGA','TIPO CARGA'])||'').trim()
        }));
      });
      const latestByGR=new Map();
      tradelAll.forEach(x=>{
        const prev=latestByGR.get(x.gr); if(!prev || (x.guideDate||'')>(prev.guideDate||'') || ((x.guideDate||'')===(prev.guideDate||'') && x.sourceRow>prev.sourceRow)) latestByGR.set(x.gr,x);
      });
      const rocheMap=new Map();
      rocheSheet.rows.forEach((row,idx)=>{
        const raw=objVal(row,['DOCUMENTO']); const gr=normalizeGR(raw); if(!gr)return;
        rocheMap.set(gr,{sourceRow:idx+2,gr,rocheRaw:String(raw||''),route:cleanNumericText(objVal(row,['NroHojaRuta','NRO HOJA RUTA','HOJA DE RUTA'])),order:cleanNumericText(objVal(row,['NroPedido','NRO PEDIDO','NUMERO DE PEDIDO','NÚMERO DE PEDIDO']))});
      });

      const existingMap=new Map(); [...state.records,...state.review].forEach(r=>existingMap.set(normalizeGR(r.gr),r));
      const cutoff=$('#importFromDate').value||'';
      const correct=[], review=[], existing=[], changes=[], skippedHistorical=[];
      latestByGR.forEach(t=>{
        const rr=rocheMap.get(t.gr), issues=[];
        if(!rr){issues.push('Pedido','No encontrada en data Roche');}
        if(!t.address)issues.push('Dirección');
        const incoming={guideDate:t.guideDate,district:t.district,route:rr?.route||'',order:rr?.order||'',recipient:t.recipient,address:t.address,grt:t.grt,grRaw:t.grRaw,gr:t.gr,sourceCargoType:t.sourceCargoType,foundRoche:!!rr,rocheRaw:rr?.rocheRaw||'',issues};
        const ex=existingMap.get(t.gr);
        if(ex){
          if(String(ex.grt||'').trim()!==String(t.grt||'').trim()) changes.push({recordId:ex.id,current:ex,incoming}); else existing.push(incoming);
          return;
        }
        if(cutoff && t.guideDate && t.guideDate<cutoff){ skippedHistorical.push(incoming); return; }
        if(issues.length)review.push(incoming); else correct.push(incoming);
      });
      const rocheOnly=[]; rocheMap.forEach((r,gr)=>{if(!latestByGR.has(gr))rocheOnly.push(r);});
      return {fileName:file.name,processed:latestByGR.size,correct,review,existing,changes,rocheOnly,skippedHistorical,cutoff};
    });
  }

  $('#loadImportBtn').onclick=()=>$('#dataImportFile').click();
  $('#dataImportFile').addEventListener('change',async e=>{
    const file=e.target.files?.[0]; if(!file)return;
    try{ pendingImport=await parseImportWorkbook(file); renderImport(); toast('Archivo analizado. Revisa la vista previa antes de confirmar.'); }
    catch(err){ console.error(err); pendingImport=null; toast(err.message||'No pude leer el Excel',true); }
    finally{ e.target.value=''; }
  });
  $('#confirmCorrectImport').onclick=()=>{
    if(!pendingImport || !pendingImport.correct.length){toast('No hay nuevas GR correctas para confirmar',true);return;}
    pendingImport.correct.forEach(x=>state.records.push(blankImportedRecord(x)));
    pendingImport.review.forEach(x=>state.review.push({...blankImportedRecord(x),imported:false,reviewResolved:false}));
    state.rocheOnly=pendingImport.rocheOnly.slice(0,200);
    audit('Importación confirmada',`${pendingImport.fileName}: ${pendingImport.correct.length} nuevas GR · ${pendingImport.review.length} por revisar`);
    pendingImport.correct=[]; pendingImport.review=[]; saveState(); renderAll(); toast('Nuevas GR importadas');
  };

  function confirmGRTChange(idx){
    if(!pendingImport)return; const c=pendingImport.changes[idx]; if(!c)return;
    const r=getRecord(c.recordId); if(!r)return;
    if(!confirm(`¿Reemplazar la GRT de ${r.gr}?\n\nActual: ${r.grt}\nNueva: ${c.incoming.grt}`))return;
    const old=r.grt, n=c.incoming;
    r.grtHistory=r.grtHistory||[]; r.grtHistory.push({at:nowIso(),user:state.currentUser,oldGRT:old,newGRT:n.grt,reason:'Cambio de GRT confirmado desde Importar data'});
    r.grt=n.grt; r.guideDate=n.guideDate||r.guideDate; r.district=n.district||r.district; r.route=n.route||r.route; r.order=n.order||r.order; r.recipient=n.recipient||r.recipient; r.address=n.address||r.address;
    r.audit=r.audit||[]; r.audit.push({at:nowIso(),user:state.currentUser,action:'Cambio de GRT',detail:`${old} → ${r.grt}`});
    pendingImport.changes.splice(idx,1); saveState(); audit('Cambio de GRT confirmado',`${r.gr}: ${old} → ${r.grt}`); renderAll(); toast('GRT vigente actualizada');
  }

  function renderImport(){
    const initialMode=!pendingImport;
    if(initialMode){
      $('#importProcessed').textContent=(window.ROCHE_PILOT_META?.normalizedGuides||SEED.length);
      $('#importCorrect').textContent=0;
      $('#importReview').textContent=state.review.filter(x=>!x.reviewResolved).length;
      $('#importExisting').textContent=state.records.length;
      $('#confirmCorrectImport').disabled=true;
      $('#importMessage').innerHTML=`Data inicial: <b>${state.records.length} GR operativas</b> y <b>${state.review.filter(x=>!x.reviewResolved).length} por revisar</b>. Tipo, documentación, observaciones y seguimiento empiezan en blanco.`;
    }else{
      $('#importProcessed').textContent=pendingImport.processed;
      $('#importCorrect').textContent=pendingImport.correct.length;
      $('#importReview').textContent=pendingImport.review.length;
      $('#importExisting').textContent=pendingImport.existing.length;
      $('#confirmCorrectImport').disabled=pendingImport.correct.length===0;
      $('#importMessage').innerHTML=`<b>${esc(pendingImport.fileName)}</b> · Nuevas correctas: ${pendingImport.correct.length} · Por revisar: ${pendingImport.review.length} · Ya existentes: ${pendingImport.existing.length} · Cambios de GRT: ${pendingImport.changes.length}${pendingImport.skippedHistorical.length?` · Histórico anterior a ${fmtDate(pendingImport.cutoff)} omitido: ${pendingImport.skippedHistorical.length}`:''}.`;
    }

    const maxDate=maxLoadedGuideDate(); if($('#importFromDate') && !$('#importFromDate').value && maxDate) $('#importFromDate').value=nextDayIso(maxDate);
    const changes=pendingImport?.changes||[]; $('#grtChangesPanel').classList.toggle('hidden',changes.length===0);
    $('#grtChangesBody').innerHTML=changes.map((c,i)=>`<tr><td><b>${esc(c.current.gr)}</b></td><td>${esc(c.current.grt)}</td><td><b>${esc(c.incoming.grt)}</b></td><td>${esc(c.incoming.order||c.current.order||'—')}</td><td><button class="btn small primary" data-grt-change="${i}">Confirmar reemplazo</button></td></tr>`).join('');
    $$('[data-grt-change]').forEach(b=>b.onclick=()=>confirmGRTChange(Number(b.dataset.grtChange)));

    const pendingReviews=[...state.review.filter(x=>!x.reviewResolved)];
    if(pendingImport) pendingImport.review.forEach((x,i)=>pendingReviews.push({...blankImportedRecord(x),id:`preview_${i}`,imported:false,reviewResolved:false,_preview:true}));
    $('#reviewTableBody').innerHTML=pendingReviews.map(r=>{ const duplicate=/duplicad/i.test((r.issues||[]).join(' ')); return `<tr><td><b>${esc(r.gr)}</b></td><td>${esc(r.grt)}</td><td>${esc(r.order||'—')}</td><td>${esc(r.route||'—')}</td><td>${esc(r.recipient||'—')}</td><td>${esc(r.address||'—')}</td><td>${esc((r.issues||[]).join(' · '))}</td><td class="review-actions">${r._preview?'<span class="status warning">Se agregará al confirmar</span>':r.reviewResolved?'<span class="status completo">Confirmado</span>':`<button class="btn small primary" data-review="${r.id}">Completar</button>${duplicate?`<button class="btn small danger-outline" data-review-delete="${r.id}">Eliminar</button>`:''}`}</td></tr>`; }).join('')||'<tr><td colspan="8" class="empty-row">No hay registros por revisar.</td></tr>';
    $$('[data-review]').forEach(b=>b.onclick=()=>openReviewEdit(getRecord(b.dataset.review)));
    $$('[data-review-delete]').forEach(b=>b.onclick=()=>{ const r=getRecord(b.dataset.reviewDelete); if(!r)return; if(!confirm(`¿Eliminar ${r.gr} de Por revisar? Úsalo solo si es un duplicado/error de importación.`))return; state.review=state.review.filter(x=>String(x.id)!==String(r.id)); saveState(); audit('Duplicado eliminado de importación',r.gr); renderAll(); toast('Duplicado eliminado'); });
    const warnings=pendingImport?.rocheOnly||state.rocheOnly||[];
    $('#rocheOnlyList').innerHTML=warnings.slice(0,100).map(x=>`<div><b>${esc(x.gr)}</b><span>${x.order?'Pedido '+esc(x.order)+' · ':''}${x.route?'HR '+esc(x.route)+' · ':''}No se importa porque no existe en Tradel.</span></div>`).join('') || '<div class="muted">Sin advertencias en la última carga.</div>';
  }
  function openReviewEdit(r){
    const html=`<div class="form-grid"><div class="field"><label>GR</label><input id="revGR" value="${esc(r.gr)}"></div><div class="field"><label>GRT</label><input id="revGRT" value="${esc(r.grt)}"></div><div class="field"><label>Pedido</label><input id="revOrder" value="${esc(r.order)}"></div><div class="field"><label>HR</label><input id="revRoute" value="${esc(r.route)}"></div><div class="field span2"><label>Destinatario</label><input id="revRec" value="${esc(r.recipient)}"></div><div class="field span2"><label>Dirección</label><input id="revAddr" value="${esc(r.address)}"></div></div><div class="callout">Completa los datos faltantes usando la documentación disponible. El sistema no inventará valores.</div><div class="modal-actions"><button class="btn" id="revCancel">Cancelar</button><button class="btn primary" id="revSave">Confirmar e importar</button></div>`;
    openModal('Completar registro observado',r.gr,html,'review-modal'); $('#revCancel').onclick=closeModal; $('#revSave').onclick=()=>{
      r.gr=normalizeGR($('#revGR').value.trim()); r.grt=$('#revGRT').value.trim(); r.order=$('#revOrder').value.trim(); r.route=$('#revRoute').value.trim(); r.recipient=$('#revRec').value.trim(); r.address=$('#revAddr').value.trim();
      const missing=[]; if(!r.gr)missing.push('GR'); if(!r.grt)missing.push('GRT'); if(!r.order)missing.push('Pedido'); if(!r.route)missing.push('HR'); if(!r.recipient)missing.push('Destinatario'); if(!r.address)missing.push('Dirección'); if(missing.length){toast(`Falta completar: ${missing.join(', ')}`,true);return;}
      r.issues=[]; r.reviewResolved=true; r.imported=true; state.review=state.review.filter(x=>x.id!==r.id); state.records.push(r); saveState(); audit('Registro observado confirmado',r.gr); closeModal(); renderAll(); toast('Registro importado');
    };
  }

  // ---------- Counts / rendering ----------
  function renderBadges(){
    recalcAll(); const active=allOperational().filter(r=>!r.liquidated&&['Pendiente','Parcial'].includes(r.result));
    const partialCount=active.filter(r=>r.result==='Parcial').length;
    $('#pendingBadge').textContent=active.length; $('#readyBadge').textContent=allOperational().filter(isReady).length; $('#reviewBadge').textContent=state.review.filter(x=>!x.reviewResolved).length;
    $('#partialSidebarBadge').textContent=partialCount; $('#partialSidebarBadge').classList.toggle('hidden',partialCount===0);
  }
  function renderAll(){ renderBadges(); renderPending(); renderReady(); renderGeneral(); renderClosed(); renderHistory(); renderImport(); requestAnimationFrame(updateFloatingHScroll); }

  async function initWebApp(){
    $('#loginView').classList.remove('hidden'); $('#appView').classList.add('hidden');
    if(!db){ $('#loginError').textContent='Supabase no pudo inicializarse.'; $('#loginError').classList.remove('hidden'); return; }
    const {data}=await db.auth.getSession();
    if(data?.session?.user) await startAuthenticatedSession(data.session.user);
    setInterval(refreshRemoteIfNewer,5000);
  }
  initWebApp();
})();
